   +        nice_err(&path, file.write_all(contents.as_bytes()));
   +        nice_err(&path, file.flush());
   +    }
   +
   +    /// Remove a file with the given name from this directory.
   +    pub fn remove<P: AsRef<Path>>(&self, name: P) {
   +        let path = self.dir.join(name);
